#!/usr/bin/env ts-node

/**
 * Script to test creating a purchase order in Zoho Books with a hardcoded payload
 * 
 * This script sends the exact payload that's being generated by the sync function
 * to help debug API issues.
 * 
 * Usage:
 *   ts-node scripts/test-zoho-create-po.ts
 * 
 * Requires environment variables:
 *   - ZOHO_CLIENT_ID
 *   - ZOHO_CLIENT_SECRET
 *   - ZOHO_REFRESH_TOKEN
 *   - ZOHO_ORGANIZATION_ID (optional)
 *   - ZOHO_API_DOMAIN (optional)
 */

import { ZohoBooksAPIClient } from '../../src/lib/integrations/zoho_books/zoho_api_client';
import * as dotenv from 'dotenv';

// Load environment variables
dotenv.config();

async function testCreatePurchaseOrder() {
  try {
    console.log('🧪 Testing Zoho Books Purchase Order Creation\n');
    console.log('─'.repeat(80));

    // Check for required environment variables
    if (!process.env.ZOHO_CLIENT_ID || !process.env.ZOHO_CLIENT_SECRET || !process.env.ZOHO_REFRESH_TOKEN) {
      console.error('❌ Missing required environment variables:');
      console.error('   - ZOHO_CLIENT_ID');
      console.error('   - ZOHO_CLIENT_SECRET');
      console.error('   - ZOHO_REFRESH_TOKEN');
      console.error('\nPlease set these in your .env file.');
      process.exit(1);
    }

    // Initialize Zoho API client
    const zohoClient = new ZohoBooksAPIClient();

    // Get organization ID
    const orgId = await zohoClient.getOrganizationId();
    console.log(`✓ Connected to Zoho Books organization: ${orgId}\n`);

    // Hardcoded payload (exact payload from the error)
    const testPayload = {
      date: "2025-11-28",
      vendor_id: "2280971000000329057",
      line_items: [
        {
          name: "Dell Latitude 5420 Laptop",
          description: "Test item description",
          rate: 500,
          quantity: 2,
          unit: "EA"
        }
      ],
      reference_number: "PO000012",
      delivery_address: "Electronic City, Phase 1, Hosur Road",
      notes: "Test purchase requisition"
    };

    console.log('📋 Payload to send:\n');
    console.log(JSON.stringify(testPayload, null, 2));
    console.log('\n─'.repeat(80));
    console.log('\n🚀 Sending request to Zoho Books API...\n');

    // Send the request
    const response = await zohoClient.createPurchaseOrder(testPayload);

    console.log('✅ Success! Purchase order created in Zoho Books\n');
    console.log('─'.repeat(80));
    console.log('\n📋 Response:\n');
    console.log(JSON.stringify(response, null, 2));
    console.log('\n─'.repeat(80));
    
    if (response.purchaseorder) {
      console.log('\n✅ Purchase Order Details:');
      console.log(`   PO ID: ${response.purchaseorder.purchaseorder_id}`);
      console.log(`   PO Number: ${response.purchaseorder.purchaseorder_number}`);
      console.log(`   Vendor ID: ${response.purchaseorder.vendor_id || testPayload.vendor_id}`);
      console.log(`   Date: ${response.purchaseorder.date || testPayload.date}`);
      console.log(`   Status: ${response.purchaseorder.status || 'N/A'}`);
    }

    console.log('\n✅ Test completed successfully!\n');

  } catch (error: any) {
    console.error('\n❌ Error creating purchase order:\n');
    
    if (error.response) {
      console.error(`Status: ${error.response.status}`);
      console.error(`Response Data:`, JSON.stringify(error.response.data, null, 2));
      
      // Provide helpful error messages
      if (error.response.data?.code === 6041) {
        console.error('\n💡 Error 6041: User not associated with the organization');
        console.error('   This means the refresh token is for a different organization.');
        console.error('   Solution: Generate a new refresh token for the correct organization.');
      } else if (error.response.data?.message?.includes('Invalid value passed for Vendor ID')) {
        console.error('\n💡 Invalid Vendor ID Error:');
        console.error(`   Vendor ID is not valid.`);
        console.error('   Possible reasons:');
        console.error('   1. Vendor does not exist in Zoho Books');
        console.error('   2. Vendor is not marked as a "vendor" type (might be just a contact)');
        console.error('   3. Vendor belongs to a different organization');
        console.error('\n   Solution: Run fetch-zoho-vendors.ts to see valid vendor IDs');
      }
    } else if (error.message) {
      console.error(`Error: ${error.message}`);
    } else {
      console.error('Unknown error:', error);
    }
    
    process.exit(1);
  }
}

// Run the test
testCreatePurchaseOrder();

